// ── Mock Interview Session Timer and Ritual Scaffold ─────────────
// Use this in practice to build the habit of staying on schedule.

class InterviewSession {
  constructor(durationMinutes = 45) {
    this.totalMs = durationMinutes * 60 * 1000;
    this.startTime = null;
    this.log = [];
  }

  begin() {
    this.startTime = Date.now();
    this._record('Session started — read problem aloud before commenting.');
  }

  checkpoint(label) {
    const elapsedSec = Math.round((Date.now() - this.startTime) / 1000);
    const remainingSec = Math.round((this.totalMs - (Date.now() - this.startTime)) / 1000);
    const entry = `[${elapsedSec}s elapsed | ${remainingSec}s remaining] ${label}`;
    this.log.push(entry);
    console.log(entry);
    // Alert if behind on schedule
    if (label.includes('coding started') && elapsedSec > 15 * 60) {
      console.warn('WARNING: Still clarifying at minute 15 — compress and start coding.');
    }
    if (label.includes('code complete') && remainingSec < 7 * 60) {
      console.warn('WARNING: Less than 7 min left — prioritise testing over polish.');
    }
  }

  _record(msg) { this.log.push(msg); console.log(msg); }

  summary() {
    console.log('\n--- Session debrief log ---');
    this.log.forEach(entry => console.log(entry));
  }
}

// ── Simulated five-step ritual with realistic timestamps ──────────
const session = new InterviewSession(45);
session.begin();

session.checkpoint('Step 1: Problem read aloud — Two Sum variant with sorted array.');
session.checkpoint('Step 2: Clarified — sorted ascending, distinct values, always one solution.');
session.checkpoint('Step 3: Example built — [2,7,11,15] target=9 → indices [0,1].');
session.checkpoint('Step 3b: Edge case — [1,3] target=4 → [0,1]; minimum array size.');
session.checkpoint('Step 4: Approach — Two Pointers O(n) time O(1) space. Stated to interviewer.');
session.checkpoint('Step 5: Coding started.');
session.checkpoint('Core loop written. Edge case guard added for empty input.');
session.checkpoint('Code complete. Starting manual trace.');
session.checkpoint('Trace verified: [2,7,11,15] target=9 → left=0,right=3 → 2+15>9 → right=2 → 2+11>9 → right=1 → 2+7=9 ✓');
session.checkpoint('Complexity stated: O(n) time, O(1) space. No auxiliary structure needed.');
session.checkpoint('Follow-up: what if unsorted? — Hash map O(n) approach described.');
session.summary();

// ── Think-aloud phrase bank — practise these until automatic ─────
const thinkAloudPhrases = [
  'Let me read this all the way through before I say anything.',
  'Before I start, I want to clarify — is the input array sorted?',
  'I am noticing the phrase "contiguous subarray" — that is a sliding window signal.',
  'My first instinct is brute force O(n²) — let me see if I can do better.',
  'I will use a hash map here because I need O(1) lookup by value, not by index.',
  'Edge case to handle first: what if the input is empty? Returning early.',
  'Let me trace through my own example to verify before I declare done.',
  'I think there is an off-by-one on this boundary condition — let me check.',
  'This is O(n) time and O(n) space for the hash map. Can I get to O(1) space?',
  'I have been silent for a moment — I am thinking about whether a monotonic stack applies here.',
];
console.log(`Think-aloud phrase bank: ${thinkAloudPhrases.length} prompts loaded.`);

// ── Post-Mock Debrief Template as a Data Structure ───────────────
// Track your improvement quantitatively across sessions.

class MockDebrief {
  constructor(sessionNumber) {
    this.session = sessionNumber;
    this.date = new Date().toISOString().split('T')[0];
    this.problem = '';
    this.pattern = '';
    this.recognitionTimeMin = null;   // how many minutes until pattern clicked
    this.clarificationMissed = [];    // questions you wish you had asked
    this.edgeCasesForgotten = [];     // empty input, negatives, duplicates, overflow
    this.timeDistribution = {
      clarifyMin: null,
      approachMin: null,
      codingMin: null,
      testingMin: null,
    };
    this.codeQuality = {
      descriptiveNames: false,
      complexityStatedCorrectly: false,
      edgeCasesHandled: false,
      codeModular: false,
    };
    this.oneImprovement = '';         // ONE specific thing, not a list
    this.antiPatternsObserved = [];   // from the anti-pattern list
  }

  score() {
    // Rough quality score for trending over time
    let points = 0;
    if (this.recognitionTimeMin !== null && this.recognitionTimeMin <= 3) points += 2;
    if (this.clarificationMissed.length === 0) points += 2;
    if (this.edgeCasesForgotten.length === 0) points += 2;
    if (Object.values(this.codeQuality).every(Boolean)) points += 4;
    if (this.antiPatternsObserved.length === 0) points += 2;
    return { score: points, max: 12 };
  }

  report() {
    const { score, max } = this.score();
    return [
      `Session ${this.session} (${this.date})`,
      `Problem: ${this.problem}`,
      `Pattern: ${this.pattern} — recognised in ${this.recognitionTimeMin} min`,
      `Missed clarifications: ${this.clarificationMissed.join(', ') || 'none'}`,
      `Forgotten edge cases: ${this.edgeCasesForgotten.join(', ') || 'none'}`,
      `Anti-patterns: ${this.antiPatternsObserved.join(', ') || 'none'}`,
      `Session score: ${score}/${max}`,
      `Next improvement: ${this.oneImprovement}`,
    ].join('\n');
  }
}

// Example filled debrief
const debrief = new MockDebrief(7);
debrief.problem = 'Longest Substring Without Repeating Characters';
debrief.pattern = 'Sliding Window';
debrief.recognitionTimeMin = 4; // took 4 minutes — target: 2
debrief.clarificationMissed = ['Is input ASCII or full Unicode?'];
debrief.edgeCasesForgotten = ['empty string', 'all same characters'];
debrief.codeQuality = { descriptiveNames: true, complexityStatedCorrectly: true,
                         edgeCasesHandled: false, codeModular: true };
debrief.antiPatternsObserved = ['long silence at minute 6', 'declared done without testing'];
debrief.oneImprovement = 'Add empty input guard before the main loop — every session.';

console.log(debrief.report());
console.log(debrief.score()); // { score: 6, max: 12 } — 7 more sessions to track trend
